{"implementation":"def solve(case):
    payload = case.get('payload', {})
    attempts = payload.get('attempts', [])
    max_attempts = payload.get('max_attempts', 0)
    if not attempts:
        return {'decision': 'retry', 'next_index': 1, 'memory_update': {}}
    latest = attempts[-1]
    if latest.get('success'):
        return {'decision': 'stop', 'next_index': len(attempts), 'memory_update': {'reflection': latest.get('reflection', ''), 'signature': latest.get('failure_signature', '')}}
    if len(attempts) >= max_attempts:
        return {'decision': 'stop', 'next_index': len(attempts), 'memory_update': {'reflection': latest.get('reflection', ''), 'signature': latest.get('failure_signature', '')}}
    current_sig = latest.get('failure_signature')
    for a in attempts[:-1]:
        if a.get('failure_signature') == current_sig:
            return {'decision': 'stop', 'next_index': len(attempts), 'memory_update': {'reflection': latest.get('reflection', ''), 'signature': current_sig}}
    return {'decision': 'retry', 'next_index': len(attempts) + 1, 'memory_update': {'reflection': latest.get('reflection', ''), 'signature': latest.get('failure_signature', '')}}"}
